317	std::optional<ToolError> PrinterConversation::preflight_tool(ToolHandler handler, ToolActivity& activity) const
318	{
319	    // Every session is offered every printer tool, so the tool list stays the
320	    // same for the prompt cache; what a call may do depends on the session.
321	    // Finding and adding a printer belongs to an Add session: a Change or
322	    // Connect session is about a printer the person already has, and an add
323	    // there would save another printer and move the session onto it.
324	    if (m_mode != ConversationMode::Add && (handler == ToolHandler::PrinterIdentify || handler == ToolHandler::PrinterAdd))
325	        return ToolError{"not_in_this_conversation",
326	                         "This conversation is about " + m_printer_name + ", which is already set up; printers are not "
327	                         "found or added here. Tell the person that another printer is added with + Add printer on Home."};
328	    // The settings tools reach the project too; here they reach this
329	    // printer's own settings, and nothing else.
330	    if (handler == ToolHandler::SettingsSearch || handler == ToolHandler::SettingsGet ||
331	        handler == ToolHandler::SettingsPreviewPatch || handler == ToolHandler::SettingsApplyPatch) {
332	        if (m_printer_name.empty())
333	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
334	        const json arguments = json::parse(activity.arguments_json);
335	        if (arguments.value("scope", std::string()) != "printer")
336	            return ToolError{"not_in_this_conversation", "Only this printer's settings are changed here: pass scope printer and "
337	                                                         "target.preset \"" + m_printer_name + "\"."};
338	        if (arguments.at("target").value("preset", std::string()) != m_printer_name)
339	            return ToolError{"other_printer", "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
340	                                              "changed from Printer settings… in its menu on Home."};
341	        return std::nullopt;
342	    }
343	    // A stock profile holds nothing of the person's own: a nozzle size or a
344	    // connection is saved on a printer they have added.
345	    if (about().stock && (handler == ToolHandler::PrinterChange || handler == ToolHandler::PrinterConnect ||
346	                          handler == ToolHandler::PrinterConnectionStatus))
347	        return ToolError{"stock_profile", "\"" + m_printer_name + "\" is the settings JusPrin comes with for this model, not a "
348	                                          "printer the person has added, so its nozzle and connection are not saved. Its other "
349	                                          "settings are changed by saving a copy, which is then theirs (settings_apply_patch with "
350	                                          "persistAs). To keep a nozzle or a connection, they add the printer with + Add printer "
351	                                          "on Home."};
352	    // A change is to the printer this session is about, and only once there
353	    // is one. The model sometimes names a printer on the network instead.
354	    if (handler == ToolHandler::PrinterChange) {
355	        if (saved(m_printer_name).name.empty())
356	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
357	        const std::string name = json::parse(activity.arguments_json).value("printerName", std::string());
358	        if (name != m_printer_name)
359	            return ToolError{saved(name).name.empty() ? "unknown_printer" : "other_printer",
360	                             "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
361	                             "changed from Printer settings… in its menu on Home."};
362	        return std::nullopt;
363	    }
364	    if (handler != ToolHandler::PrinterConnect)
365	        return std::nullopt;
366	    json              arguments = json::parse(activity.arguments_json);
367	    const std::string name      = m_printer_name;
368	    if (saved(name).name.empty())
369	        return ToolError{"no_printer", "There is no saved printer to connect yet: add one first."};
370	
371	    const PrinterConnectionInfo info = m_backend.connection(name);
372	    // No printer can be listed without the plug-in, so the reason is that,
373	    // not an unknown device.
374	    if (info.needs_network_plugin)
375	        return ToolError{"connection_unavailable", info.message};
376	    if (info.provider == "bambu") {
377	        // The person names the printer as its list shows it, so its name
378	        // finds it as surely as its id.
379	        const std::string device = arguments.value("deviceId", std::string());
380	        const auto found = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& candidate) {
381	            return candidate.lan_mode && (candidate.id == device || candidate.name == device);
382	        });
383	        if (found == info.candidates.end()) {
384	            std::string listed;
385	            for (const ConnectionCandidate& candidate : info.candidates)
386	                if (candidate.lan_mode)
387	                    listed += (listed.empty() ? "" : ", ") + candidate.id + " (" + candidate.name + ")";
388	            return ToolError{"unknown_device", listed.empty() ? "No printer in LAN mode is on the network now; check again with printer_connection_status." :
389	                                                                "Pass the deviceId of one of these printers in LAN mode: " + listed + "."};
390	        }
391	        activity.title = "Connect to " + found->name;
392	        arguments["deviceId"] = found->id;
393	        arguments["target"]   = found->name;
394	    } else if (info.provider == "host") {
395	        // The registry has already refused a hostType without an address; a
396	        // deviceId here names a Bambu Lab printer this one is not.
397	        if (!arguments.contains("hostType"))
398	            return ToolError{"address_needed", "Pass hostType and the address the person gave."};
399	        activity.title      = "Connect to " + arguments["address"].get<std::string>();
400	        arguments["target"] = arguments["address"];
401	    } else
402	        return ToolError{"connection_unavailable", info.message};
403	    // Which field the local form asks for, and the printer it named.
404	    arguments["provider"]    = info.provider;
405	    arguments["printerName"] = name;
406	    activity.arguments_json = arguments.dump();
407	    return std::nullopt;
408	}
