449	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
450	{
451	    std::vector<const CatalogPrinter*> printers;
452	    for (const json& id : arguments.at("catalogIds")) {
453	        const CatalogPrinter* printer = catalog_entry(id);
454	        if (printer == nullptr)
455	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
456	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
457	            printers.push_back(printer);
458	    }
459	    if (printers.size() > kMaximumCandidates)
460	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
461	    const bool stated = said_nozzle(arguments);
462	    for (const CatalogPrinter* printer : printers)
463	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
464	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
465	
466	    json cards = json::array();
467	    json found = json::array();
468	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
469	    for (const CatalogPrinter* printer : printers) {
470	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
471	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
472	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
473	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
474	        found.push_back(json{{"catalogId", printer->id},
475	                             {"brand", printer->vendor_name},
476	                             {"model", printer->model_name},
477	                             {"buildVolume", printer->build_volume},
478	                             {"nozzles", printer->nozzles},
479	                             {"assumed", json{{"nozzle", nozzle},
480	                                              {"plate", nullable(printer->default_plate)},
481	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
482	                             {"alreadyYours", yours}});
483	    }
484	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
485	                            {"kind", "printers"}, {"printers", std::move(cards)}});
486	    m_host.session_changed();
487	    return ok(json{{"printers", std::move(found)}});
488	}
