490	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
491	{
492	    const std::string     id      = arguments.at("catalogId");
493	    const CatalogPrinter* printer = catalog_entry(id);
494	    if (printer == nullptr)
495	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
496	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
497	    if (!ships(printer->nozzles, nozzle))
498	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
499	    // A second yes to the same printer is the same printer, not another one.
500	    if (const auto added = m_added.find(id); added != m_added.end())
501	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
502	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
503	                                           "opening Add printer again.");
504	
505	    // Adding never authenticates: credentials belong to connecting, so a
506	    // failed connection cannot repeat this save.
507	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
508	                              printer->filament_for(nozzle), printer->display_name(), {}};
509	    SavedPrinter      added;
510	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
511	        return refuse("add_failed", problem);
512	    const SavedPrinter now = saved(added.name);
513	    if (now.name.empty())
514	        throw std::logic_error("A successful add did not save a printer");
515	    m_printer_name = now.name;
516	    m_added[id]    = now.name;
517	    // The receipt is the app's, drawn from what was saved: the model's reply
518	    // can word the moment any way, but whether it happened is not its to say.
519	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
520	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
521	    m_host.printers_changed(now.name);
522	    m_host.session_changed();
523	    return ok(json{{"printer", printer_json(now)}});
524	}
525	
526	Result PrinterConversation::change(const json& arguments)
527	{
528	    // preflight_tool has checked that this is the session's own printer.
529	    const std::string  name = arguments.at("printerName");
530	    const SavedPrinter now  = saved(name);
531	    // What is loaded is the printer's to report, not the conversation's to
532	    // record: the nozzle is the one physical change this tool saves.
533	    if (!said_nozzle(arguments))
534	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
535	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
536	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
537	
538	    ChangePrinterRequest request;
539	    request.name = name;
540	    if (arguments["nozzle"].get<double>() != now.nozzle)
541	        request.nozzle = arguments["nozzle"].get<double>();
542	    if (!request.nozzle)
543	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
544	
545	    SavedPrinter             changed;
546	    std::vector<std::string> discarded;
547	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
548	        return refuse("change_failed", problem);
549	    const SavedPrinter after = saved(name);
550	    json               what  = json::array();
551	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
552	    m_host.printers_changed();
553	    m_host.session_changed();
554	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
555	}
