743	// -- The printer form --------------------------------------------------------
744	
745	void PrinterConversation::open_form()
746	{
747	    // A printer is added in an Add session only, as printer_add is.
748	    if (m_mode != ConversationMode::Add)
749	        return;
750	    // An earlier form's read is waited for first: the backend's copy of the
751	    // person's own presets is what that read is using.
752	    m_form.reset();
753	    m_backend.prepare_setup_options();
754	    PrinterForm form;
755	    // A machine that already has a printer is that printer, and the form
756	    // adds new ones; a model the catalogue lacks cannot be set up from it.
757	    const std::vector<SavedPrinter> printers = m_backend.saved_printers();
758	    for (DiscoveredPrinter& found : m_backend.nearby_printers()) {
759	        if (std::any_of(printers.begin(), printers.end(),
760	                        [&found](const SavedPrinter& printer) { return printer.device_id == found.stable_id; }))
761	            continue;
762	        const auto& catalog = m_backend.catalog();
763	        const auto  model   = std::find_if(catalog.begin(), catalog.end(), [&found](const CatalogPrinter& printer) {
764	            return !printer.device_model_id.empty() && printer.device_model_id == found.device_model_id;
765	        });
766	        if (model != catalog.end())
767	            form.nearby.emplace_back(std::move(found), model->id);
768	    }
769	    m_form = std::move(form);
770	    m_host.session_changed();
771	}
772	
773	void PrinterConversation::ask_form_options(const json& payload)
774	{
775	    if (!m_form)
776	        return;
777	    const std::string     id      = payload.value("catalogId", std::string());
778	    const double          nozzle  = payload.value("nozzle", 0.);
779	    const CatalogPrinter* printer = catalog_entry(id);
780	    if (printer == nullptr || !ships(printer->nozzles, nozzle))
781	        return;
782	    if (m_form->asked_id == id && m_form->asked_nozzle == nozzle)
783	        return;
784	    m_form->asked_id     = id;
785	    m_form->asked_nozzle = nozzle;
786	    m_form->options.reset();
787	    m_form->error.clear();
788	    // A read still running for the last choice is waited for here; its
789	    // answer is no longer wanted.
790	    m_form->reading = std::async(std::launch::async, [&backend = m_backend, id, nozzle] { return backend.setup_options(id, nozzle); });
791	    m_host.session_changed();
792	}
793	
794	void PrinterConversation::finish_form(const json& payload)
795	{
796	    if (!m_form)
797	        return;
798	    const std::string     id      = payload.value("catalogId", std::string());
799	    const double          nozzle  = payload.value("nozzle", 0.);
800	    const CatalogPrinter* printer = catalog_entry(id);
801	    // The page finishes from the options it was sent; anything else is a
802	    // page out of step with the app, and nothing is saved from it.
803	    const auto refuse_form = [this](const std::string& why) {
804	        m_form->error = why;
805	        m_host.session_changed();
806	    };
807	    const std::optional<SetupOptions>& options = m_form->options;
808	    if (printer == nullptr || !options || options->catalog_id != id || options->nozzle != nozzle || !options->error.empty())
809	        return refuse_form("The form was out of date. Choose the printer again.");
810	
811	    std::optional<int> plate;
812	    std::string        plate_label;
813	    if (!options->plates.empty()) {
814	        const int  type  = payload.value("plate", 0);
815	        const auto found = std::find_if(options->plates.begin(), options->plates.end(),
816	                                        [type](const PlateOption& option) { return option.type == type; });
817	        if (found == options->plates.end())
818	            return refuse_form("Choose the plate on this printer.");
819	        plate       = type;
820	        plate_label = found->label;
821	    }
822	
823	    // The filament to start with: one that fits, which is installed with
824	    // the printer; one of the person's own; one made for other printers,
825	    // which is copied for this one; or a preset the person makes in
826	    // OrcaSlicer's Create filament window once the printer is added.
827	    const bool        create   = payload.value("create", false);
828	    const std::string filament = create ? std::string() : payload.value("filament", std::string());
829	    const auto        in       = [&filament](const std::vector<FilamentOption>& list) -> const FilamentOption* {
830	        const auto found = std::find_if(list.begin(), list.end(), [&filament](const FilamentOption& option) { return option.name == filament; });
831	        return found == list.end() ? nullptr : &*found;
832	    };
833	    const FilamentOption* fitting = filament.empty() ? nullptr : in(options->filaments);
834	    const FilamentOption* other   = filament.empty() ? nullptr : in(options->others);
835	    const FilamentOption* own     = filament.empty() ? nullptr : in(options->own);
836	    if (!filament.empty() && fitting == nullptr && other == nullptr && own == nullptr)
837	        return refuse_form("That filament is no longer on the list. Choose another.");
838	
839	    const std::string device = payload.value("deviceId", std::string());
840	    const auto        found  = std::find_if(m_form->nearby.begin(), m_form->nearby.end(),
841	                                            [&device](const auto& entry) { return entry.first.stable_id == device; });
842	    if (!device.empty() && (found == m_form->nearby.end() || found->second != id))
843	        return refuse_form("That printer is no longer on the list. Choose it again.");
844	
845	    // The printer is installed with a filament that fits: the chosen one, or
846	    // the profile's default until the chosen one is in place.
847	    AddPrinterRequest request{printer->vendor_id, printer->model_id, number_text(nozzle),
848	                              fitting != nullptr ? fitting->name : options->default_filament, printer->display_name(), device, plate};
849	    SavedPrinter      added;
850	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
851	        return refuse_form(problem);
852	    const SavedPrinter now = saved(added.name);
853	    if (now.name.empty())
854	        throw std::logic_error("A successful add did not save a printer");
855	
856	    const auto label_of = [&options](const std::string& name) {
857	        for (const auto* list : {&options->filaments, &options->others, &options->own})
858	            for (const FilamentOption& option : *list)
859	                if (option.name == name)
860	                    return option.label;
861	        return name;
862	    };
863	    std::string starting = fitting != nullptr ? fitting->label : label_of(options->default_filament);
864	    std::string filament_note;
865	    if (own != nullptr || other != nullptr) {
866	        const FilamentOption& chosen = own != nullptr ? *own : *other;
867	        const bool            copy   = !chosen.made_for.empty();
868	        std::string           used;
869	        if (const std::string problem = m_backend.start_with_filament(now.name, chosen.name, copy, used); !problem.empty())
870	            filament_note = " " + chosen.label + " could not be used: " + problem + " It starts with " + starting + ".";
871	        else if (copy)
872	            starting = "a copy of " + chosen.label + " saved for this printer as " + used;
873	        else
874	            starting = "their own preset " + used;
875	    }
876	    if (create) {
877	        const std::string made = m_backend.create_filament_preset(now.name);
878	        filament_note = made.empty() ? " The person opened the Create filament window and made no preset for this printer, so it starts with " +
879	                                           starting + "."
880	                                     : " The person made the filament preset " + made + " in the Create filament window; it is in slot 1.";
881	    }
882	
883	    std::string note = "The person added " + now.name + " themselves with the printer form: " + printer->display_name() + ", " +
884	                       number_text(nozzle) + " mm nozzle";
885	    if (!plate_label.empty())
886	        note += ", " + plate_label;
887	    if (!create && filament_note.empty() && !starting.empty())
888	        note += ", starting with " + starting;
889	    note += "." + filament_note;
890	    if (!device.empty())
891	        note += " It is linked to the printer " + found->first.name + " found on the network, which is not connected yet.";
892	
893	    m_form.reset();
894	    m_printer_name = now.name;
895	    m_added[id]    = now.name;
896	    m_host.post_note(note);
897	    m_host.printers_changed(now.name);
898	    m_host.session_changed();
899	    m_host.start_turn();
900	}
