344	    if (!agent->get_printer_agent() || agent->get_printer_agent()->get_agent_info().id != wanted) {
345	        // A connection gesture selects the networking provider, not a slicing
346	        // preset. NetworkAgent owns callback transfer and disconnects the old
347	        // provider; the open project's settings and unsaved edits stay intact.
348	        // Orca's profile-driven policy takes the provider back the next time
349	        // the printer profile changes; connecting again reinstalls it.
350	        auto provider = NetworkAgentFactory::create_printer_agent_by_id(
351	            wanted, agent->get_cloud_agent(BBL_CLOUD_PROVIDER), Slic3r::data_dir());
352	        if (!provider)
353	            throw std::runtime_error("The registered Bambu printer agent could not be created");
354	        agent->set_printer_agent(std::move(provider));
355	        wxGetApp().sidebar().update_all_preset_comboboxes();
356	    }
357	    agent->start_discovery(true, false);
358	}
