488	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
489	                                               const std::string& access_code)
490	{
491	    // The same printer asked for again keeps waiting; anything else replaces
492	    // the attempt below.
493	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
494	        connection(name).state == "connecting")
495	        return {};
496	    const auto info = connection(name);
497	    if (info.provider != "bambu" || info.state == "unavailable")
498	        return info.message;
499	    if (std::none_of(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; }))
500	        return "Choose a matching printer from the refreshed list.";
501	    auto* devices = wxGetApp().getDeviceManager();
502	    MachineObject* machine = devices->get_my_machine(device_id);
503	    if (!machine)
504	        machine = devices->get_local_machine(device_id);

