88	    std::vector<DiscoveredPrinter> network;
89	    std::vector<SavedPrinter>      saved;
90	    std::string                    refusal;
91	
92	    std::vector<AddPrinterRequest>    added;
93	    std::vector<ChangePrinterRequest> changed;
94	    int                               manual_setups{0};
95	    std::vector<std::string>          settings_opened;
96	
97	    // OrcaSlicer's own printer profiles a person could select.
98	    std::vector<SavedPrinter>      stock;
99	
100	    const std::vector<CatalogPrinter>& catalog() const override { return catalogue; }
101	    std::vector<DiscoveredPrinter>     network_printers() const override { return network; }
102	    // Everything found, the printers without an access code included.
103	    std::vector<DiscoveredPrinter>     nearby;
104	    std::vector<DiscoveredPrinter>     nearby_printers() const override { return nearby; }
105	    // What the printer form is offered, by catalogue id and nozzle.
106	    std::map<std::pair<std::string, double>, SetupOptions> options;
107	    SetupOptions setup_options(const std::string& id, double nozzle) const override
108	    {
109	        SetupOptions found = options.at({id, nozzle});
110	        found.catalog_id   = id;
111	        found.nozzle       = nozzle;
112	        return found;
113	    }
114	    std::vector<SavedPrinter>          saved_printers() const override { return saved; }
115	    SavedPrinter                       stock_printer(const std::string& name) const override
116	    {
117	        for (SavedPrinter printer : stock)
118	            if (printer.name == name) {
119	                printer.stock = true;
120	                return printer;
121	            }
122	        return {};
123	    }
124	
125	    // Saves the printer into `saved`, as the Orca backend does.
126	    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& result) override
127	    {
128	        added.push_back(request);
129	        if (!refusal.empty())
130	            return refusal;
131	        result.name     = request.name;
132	        result.model    = request.name;
133	        result.model_id = request.model_id;
134	        result.nozzle   = std::stod(request.variant);
135	        saved.push_back(result);
136	        return {};
137	    }
138	    // Saves the change into `saved`, as the Orca backend does.
139	    std::vector<std::string> dropped; // what a change reports it discarded
140	    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& result, std::vector<std::string>& discarded) override
141	    {
142	        changed.push_back(request);
143	        discarded = dropped;
144	        if (!refusal.empty())
145	            return refusal;
146	        for (SavedPrinter& printer : saved)
147	            if (printer.name == request.name) {
148	                if (request.nozzle)
149	                    printer.nozzle = *request.nozzle;
150	                result = printer;
151	            }
152	        return {};
153	    }
154	    std::vector<std::string> removed;
155	    // Takes the printer out of `saved`, as the Orca backend does.
156	    std::string remove_printer(const std::string& name) override
157	    {
158	        removed.push_back(name);
159	        if (!refusal.empty())
160	            return refusal;
161	        saved.erase(std::remove_if(saved.begin(), saved.end(), [&name](const SavedPrinter& printer) { return printer.name == name; }),
162	                    saved.end());
163	        return {};
164	    }
165	    ManualPrinterResult      manual_result;
166	    PrinterConnectionInfo    connection_info;
167	    std::vector<std::string> prepared;
168	    std::string              connection_error;
169	    // What each connect was handed, the credential included.
170	    std::vector<std::vector<std::string>> connects;
171	    PrinterConnectionInfo connection(const std::string&) override { return connection_info; }
172	    void prepare_connection(const std::string& name) override { prepared.push_back(name); }
173	    std::string connect_printer(const std::string& name, const std::string& device, const std::string& code) override
174	    {
175	        connects.push_back({name, device, code});
176	        return connection_error;
177	    }
178	    std::string connect_host(const std::string& name, const std::string& type, const std::string& address,
179	                             const std::string& key) override
180	    {
181	        connects.push_back({name, type, address, key});
182	        return connection_error;
183	    }
184	    std::vector<std::string> cancelled;
185	    void cancel_connection(const std::string& name) override { cancelled.push_back(name); }
186	    ManualPrinterResult run_manual_setup() override { ++manual_setups; return manual_result; }
187	    // What each start_with_filament was handed, and what it answers.
188	    std::vector<std::tuple<std::string, std::string, bool>> starts;
189	    std::string                                             start_problem;
190	    std::string start_with_filament(const std::string& printer, const std::string& filament, bool copy, std::string& used) override
191	    {
192	        starts.emplace_back(printer, filament, copy);
193	        if (!start_problem.empty())
194	            return start_problem;
195	        used = copy ? filament + " @" + printer : filament;
