446	std::string PrinterConversation::unknown_device_text(const PrinterConnectionInfo& info, const std::string& asked) const
447	{
448	    // What it was asked for may be a printer the app has seen and does not
449	    // offer. An empty id or address is not a match for one with none known.
450	    const auto wanted = std::find_if(info.candidates.begin(), info.candidates.end(), [&asked](const ConnectionCandidate& candidate) {
451	        return !candidate.lan_mode && !asked.empty() && (candidate.id == asked || candidate.name == asked || candidate.address == asked);
452	    });
453	    if (wanted != info.candidates.end())
454	        return not_offered_text(*wanted) + " It cannot be connected as it is. " + kPersonsChoice;
455	
456	    std::string listed;
457	    std::string others;
458	    bool        in_cloud_mode = false;
459	    for (const ConnectionCandidate& candidate : info.candidates)
460	        if (candidate.lan_mode)
461	            listed += (listed.empty() ? "" : ", ") + candidate.id + " (" + candidate.name + ")";
462	        else {
463	            others += " " + not_offered_text(candidate);
464	            in_cloud_mode = in_cloud_mode || !candidate.account_only;
465	        }
466	    return (listed.empty() ? search_text() : "Pass the deviceId of one of these printers in LAN mode: " + listed + ".") + others +
467	           (in_cloud_mode ? std::string(" ") + kPersonsChoice : std::string());
