727	void PrinterConversation::watch_search(std::chrono::steady_clock::time_point now)
728	{
729	    // An attempt under way is read by tick alone: reading a connection can
730	    // settle it.
731	    if (!m_search || m_search->found || !m_connecting.empty() ||
732	        now - m_search->last_look < (m_search->said_none || m_search->port != DiscoveryPort::Ours ? std::chrono::seconds(kSearchLateLook) :
733	                                                                                                       std::chrono::seconds(kConnectionLook)))
734	        return;
735	    m_search->last_look = now;
736	    const PrinterConnectionInfo info = m_backend.connection(m_prepared);
737	    // The printer was renamed or removed, or nothing can reach the network now.
738	    if (info.provider != "bambu" || info.state == "unavailable") {
739	        m_search.reset();
740	        return;
741	    }
742	    if (info.state == "verified") {
743	        m_search->found = true;
744	        return;
745	    }
746	    std::string note;
747	    if (found_on_network(info)) {
748	        m_search->found = true;
749	        bool in_cloud_mode = false;
750	        for (const ConnectionCandidate& candidate : info.candidates) {
751	            if (candidate.account_only)
752	                continue;
753	            in_cloud_mode = in_cloud_mode || !candidate.lan_mode;
754	            note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) +
755	                    (candidate.lan_mode ? " in LAN mode, which can be connected" : " with LAN Only off, which cannot be connected as it is");
756	        }
757	        note += ".";
758	        if (in_cloud_mode)
759	            note += std::string(" ") + kPersonsChoice;
760	    } else if (now - m_search->started < kSearchWait)
761	        return;
762	    else {
763	        // Checked only once discovery has had time to bind: the check itself
764	        // binds the port for a moment, which could cost discovery its own bind.
765	        const DiscoveryPort port = m_backend.discovery_port();
766	        if (port == m_search->port && (port != DiscoveryPort::Ours || m_search->said_none))
767	            return;
768	        m_search->port = port;
769	        if (port == DiscoveryPort::Taken)
770	            note = kPortTaken;
771	        else if (port == DiscoveryPort::Free)
772	            note = kNotListening;
773	        else {
774	            m_search->said_none = true;
775	            note = "The network search has listened for " + std::to_string(kSearchWait.count()) +
776	                   " seconds and has found no printer of this model. The app posts another note if one appears.";
777	        }
778	    }
779	    m_host.post_note(note);
780	    m_host.session_changed();
781	    m_host.start_turn();
782	}
